CREATE DATABASE e_commerce;

use e_commerce;

CREATE TABLE customers (
    customer_id    INT PRIMARY KEY,
    name           VARCHAR(100),
    email          VARCHAR(100),
    city           VARCHAR(50),
    country        VARCHAR(50),
    signup_date    DATE
);

